scripts.inversions:
def solve(inputs: dict) -> float:
    values = [int(inputs[k]) for k in sorted(inputs.keys())]
    n = len(values)
    count = 0
    for i in range(n):
        for j in range(i+1, n):
            if values[i] > values[j]:
                count += 1
    return float(count)

